{
  "物品名称": "少主守护铃",
  "物品类型": "关键剧情道具",
  "外观描述": "一个小巧精致的铃铛，由银色金属制成，上面刻有苇名家的家纹，系着一根红色的绳结。",
  "获取方式": {
    "地点": "苇名城城邑，通往大手门的桥附近",
    "NPC": "老婆婆（英麻的养母）",
    "条件": "在击败赤鬼之后，与桥头附近的老婆婆对话获得。"
  },
  "用途": {
    "地点": "破旧寺院",
    "方式": "供奉于破旧寺院中戴着斗笠的无头佛像",
    "效果": "开启“平田宅邸（三年前）”的回忆，让狼回到三年前平田宅邸被袭击的夜晚。"
  },
  "剧情相关": [
    "该铃铛原本属于九郎，在三年前平田宅邸遇袭时遗失。",
    "老婆婆（英麻的养母）误以为狼是她的儿子，将铃铛托付给狼，希望狼能将铃铛还给九郎。",
    "通过使用少主守护铃，狼可以进入三年前的回忆，了解平田宅邸事件的真相，并发现枭的背叛行为。",
    "少主守护铃是连接过去与现在的重要线索，也是推动剧情发展的关键道具。"
  ],
  "备注": "此道具可以实现穿越，穿越回三年前的平田宅邸。"
}

